Correct Answer 1 (Use subquery with LIMIT for efficient index scan):
SELECT id, symbol, price, ts FROM (
    SELECT id, symbol, price, ts FROM ticks
    WHERE symbol = 'AAPL'
    ORDER BY ts DESC
    LIMIT 100
) AS top_ticks
ORDER BY ts DESC;

Correct Answer 2 (Use table function, if available):
CREATE FUNCTION fetch_latest_ticks(symbol varchar, n integer) RETURNS SETOF rec
AS $$
DECLARE
    r rec;
BEGIN
    FOR r IN
        SELECT id, symbol, price, ts FROM ticks
        WHERE symbol = symbol_input
        ORDER BY ts DESC
        LIMIT n
    LOOP
        RETURN NEXT r;
    END LOOP;
END;
$$ LANGUAGE plpgsql;

SELECT * FROM fetch_latest_ticks('AAPL', 10);
